buildCommand:
node -e 'const fs=require("fs");fs.mkdirSync("public/data",{recursive:true});for(const name of ["ab-test-reference", "churn", "ecommerce", "finance", "forecast", "healthcare", "manifest", "segmentation"]){const source=`${name}.json`;const destination=`public/data/${name}.json`;if(fs.existsSync(source))fs.copyFileSync(source,destination);if(!fs.existsSync(destination))throw new Error(`Missing required snapshot: ${destination}`);};fs.writeFileSync("next.config.ts",`import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  output: "export",
  trailingSlash: true,
  images: { unoptimized: true },
  poweredByHeader: false,
};

export default nextConfig;
`);' && npm run build
